921	  void adjustNumPseudos(const MCInst &Inst, int Sign);
922	
923	  template <typename Itr> void adjustNumPseudos(Itr Begin, Itr End, int Sign) {
924	    while (Begin != End)
925	      adjustNumPseudos(*Begin++, Sign);
926	  }
927	
