929	  void addPredecessor(BinaryBasicBlock *Pred);
930	
931	  /// Remove predecessor of the basic block. Don't use directly, instead
932	  /// use removeSuccessor() function.
933	  /// If \p Multiple is set to true, it will remove all predecessors that
934	  /// are equal to \p Pred. Otherwise, the first instance of \p Pred found
935	  /// will be removed. This only matters in awkward, redundant CFGs.
936	  void removePredecessor(BinaryBasicBlock *Pred, bool Multiple = true);
937	
