  static inline ChildIteratorType child_begin(NodeRef N) {
    return N->pred_begin();
  }
  static inline ChildIteratorType child_end(NodeRef N) { return N->pred_end(); }
  static unsigned getNumber(const bolt::BinaryBasicBlock *BB) {
