70	bool BinaryBasicBlock::validateSuccessorInvariants() {
71	  const MCInst *Inst = getLastNonPseudoInstr();
72	  const JumpTable *JT = Inst ? Function->getJumpTable(*Inst) : nullptr;
73	  BinaryContext &BC = Function->getBinaryContext();
74	  bool Valid = true;
75	
76	  if (JT) {
77	    // Note: for now we assume that successors do not reference labels from
78	    // any overlapping jump tables.  We only look at the entries for the jump
79	    // table that is referenced at the last instruction.
80	    const auto Range = JT->getEntriesForAddress(BC.MIB->getJumpTable(*Inst));
81	    const std::vector<const MCSymbol *> Entries(
82	        std::next(JT->Entries.begin(), Range.first),
83	        std::next(JT->Entries.begin(), Range.second));
84	    std::set<const MCSymbol *> UniqueSyms(Entries.begin(), Entries.end());
85	    for (BinaryBasicBlock *Succ : Successors) {
86	      auto Itr = UniqueSyms.find(Succ->getLabel());
87	      if (Itr != UniqueSyms.end()) {
88	        UniqueSyms.erase(Itr);
89	      } else {
90	        // Work on the assumption that jump table blocks don't
91	        // have a conditional successor.
92	        Valid = false;
93	        BC.errs() << "BOLT-WARNING: Jump table successor " << Succ->getName()
94	                  << " not contained in the jump table.\n";
95	      }
96	    }
97	    // If there are any leftover entries in the jump table, they
98	    // must be one of the function end labels.
99	    if (Valid) {
100	      for (const MCSymbol *Sym : UniqueSyms) {
101	        Valid &= (Sym == Function->getFunctionEndLabel() ||
102	                  Sym == Function->getFunctionEndLabel(getFragmentNum()));
103	        if (!Valid) {
104	          const BinaryFunction *TargetBF = BC.getFunctionForSymbol(Sym);
105	          if (TargetBF) {
106	            // It's possible for another function to be in the jump table entry
107	            // as a result of built-in unreachable.
108	            Valid = true;
109	          } else {
110	            BC.errs() << "BOLT-WARNING: Jump table contains illegal entry: "
111	                      << Sym->getName() << "\n";
112	          }
113	        }
114	        if (!Valid)
115	          break;
116	      }
117	    }
118	  } else {
119	    // Unknown control flow.
120	    if (Inst && BC.MIB->isIndirectBranch(*Inst))
121	      return true;
122	
123	    const MCSymbol *TBB = nullptr;
124	    const MCSymbol *FBB = nullptr;
125	    MCInst *CondBranch = nullptr;
126	    MCInst *UncondBranch = nullptr;
127	
128	    if (analyzeBranch(TBB, FBB, CondBranch, UncondBranch)) {
129	      switch (Successors.size()) {
130	      case 0:
131	        Valid = !CondBranch && !UncondBranch;
132	        break;
133	      case 1: {
134	        const bool HasCondBlock =
135	            CondBranch && Function->getBasicBlockForLabel(
136	                              BC.MIB->getTargetSymbol(*CondBranch));
137	        Valid = !CondBranch || !HasCondBlock;
138	        break;
139	      }
140	      case 2:
141	        Valid =
142	            CondBranch && TBB == getConditionalSuccessor(true)->getLabel() &&
143	            (UncondBranch ? FBB == getConditionalSuccessor(false)->getLabel()
144	                          : !FBB);
145	        break;
146	      }
147	    }
148	  }
149	  if (!Valid) {
150	    BC.errs() << "BOLT-WARNING: CFG invalid in " << *getFunction() << " @ "
151	              << getName() << "\n";
152	    if (JT) {
153	      BC.errs() << "Jump Table instruction addr = 0x"
154	                << Twine::utohexstr(BC.MIB->getJumpTable(*Inst)) << "\n";
155	      JT->print(errs());
156	    }
157	    getFunction()->dump();
158	  }
159	  return Valid;
160	}
