195	int32_t BinaryBasicBlock::getCFIStateAtInstr(const MCInst *Instr) const {
196	  assert(
197	      getFunction()->getState() >= BinaryFunction::State::CFG &&
198	      "can only calculate CFI state when function is in or past the CFG state");
199	
200	  const BinaryFunction::CFIInstrMapType &FDEProgram =
201	      getFunction()->getFDEProgram();
202	
203	  // Find the last CFI preceding Instr in this basic block.
204	  const MCInst *LastCFI = nullptr;
205	  bool InstrSeen = (Instr == nullptr);
206	  for (const MCInst &Inst : llvm::reverse(Instructions)) {
207	    if (!InstrSeen) {
208	      InstrSeen = (&Inst == Instr);
209	      continue;
210	    }
211	    // Ignoring OpNegateRAState CFIs here, as they dont have a "State"
212	    // number associated with them.
213	    if (Function->getBinaryContext().MIB->isCFI(Inst) &&
214	        (Function->getCFIFor(Inst)->getOperation() !=
215	         MCCFIInstruction::OpNegateRAState)) {
216	      LastCFI = &Inst;
217	      break;
218	    }
219	  }
220	
221	  assert(InstrSeen && "instruction expected in basic block");
222	
223	  // CFI state is the same as at basic block entry point.
224	  if (!LastCFI)
225	    return getCFIState();
226	
227	  // Fold all RememberState/RestoreState sequences, such as for:
228	  //
229	  //   [ CFI #(K-1) ]
230	  //   RememberState (#K)
231	  //     ....
232	  //   RestoreState
233	  //   RememberState
234	  //     ....
235	  //   RestoreState
236	  //   [ GNU_args_size ]
237	  //   RememberState
238	  //     ....
239	  //   RestoreState   <- LastCFI
240	  //
241	  // we return K - the most efficient state to (re-)generate.
242	  int64_t State = LastCFI->getOperand(0).getImm();
243	  while (State >= 0 &&
244	         FDEProgram[State].getOperation() == MCCFIInstruction::OpRestoreState) {
245	    int32_t Depth = 1;
246	    --State;
247	    assert(State >= 0 && "first CFI cannot be RestoreState");
248	    while (Depth && State >= 0) {
249	      const MCCFIInstruction &CFIInstr = FDEProgram[State];
250	      if (CFIInstr.getOperation() == MCCFIInstruction::OpRestoreState)
251	        ++Depth;
252	      else if (CFIInstr.getOperation() == MCCFIInstruction::OpRememberState)
253	        --Depth;
254	      --State;
255	    }
256	    assert(Depth == 0 && "unbalanced RememberState/RestoreState stack");
257	
258	    // Skip any GNU_args_size.
259	    while (State >= 0 && FDEProgram[State].getOperation() ==
260	                             MCCFIInstruction::OpGnuArgsSize) {
261	      --State;
262	    }
263	  }
264	
265	  assert((State + 1 >= 0) && "miscalculated CFI state");
266	  return State + 1;
267	}
