276	void BinaryBasicBlock::replaceSuccessor(BinaryBasicBlock *Succ,
277	                                        BinaryBasicBlock *NewSucc,
278	                                        uint64_t Count,
279	                                        uint64_t MispredictedCount) {
280	  Succ->removePredecessor(this, /*Multiple=*/false);
281	  auto I = succ_begin();
282	  auto BI = BranchInfo.begin();
283	  for (; I != succ_end(); ++I) {
284	    assert(BI != BranchInfo.end() && "missing BranchInfo entry");
285	    if (*I == Succ)
286	      break;
287	    ++BI;
288	  }
289	  assert(I != succ_end() && "no such successor!");
290	
291	  *I = NewSucc;
292	  *BI = BinaryBranchInfo{Count, MispredictedCount};
293	  NewSucc->addPredecessor(this);
294	}
