296	void BinaryBasicBlock::removeAllSuccessors() {
297	  SmallPtrSet<BinaryBasicBlock *, 2> UniqSuccessors(succ_begin(), succ_end());
298	  for (BinaryBasicBlock *SuccessorBB : UniqSuccessors)
299	    SuccessorBB->removePredecessor(this);
300	  Successors.clear();
301	  BranchInfo.clear();
302	}
