304	void BinaryBasicBlock::removeSuccessor(BinaryBasicBlock *Succ) {
305	  Succ->removePredecessor(this, /*Multiple=*/false);
306	  auto I = succ_begin();
307	  auto BI = BranchInfo.begin();
308	  for (; I != succ_end(); ++I) {
309	    assert(BI != BranchInfo.end() && "missing BranchInfo entry");
310	    if (*I == Succ)
311	      break;
312	    ++BI;
313	  }
314	  assert(I != succ_end() && "no such successor!");
315	
316	  Successors.erase(I);
317	  BranchInfo.erase(BI);
318	}
