324	void BinaryBasicBlock::removePredecessor(BinaryBasicBlock *Pred,
325	                                         bool Multiple) {
326	  // Note: the predecessor could be listed multiple times.
327	  bool Erased = false;
328	  for (auto PredI = Predecessors.begin(); PredI != Predecessors.end();) {
329	    if (*PredI == Pred) {
330	      Erased = true;
331	      PredI = Predecessors.erase(PredI);
332	      if (!Multiple)
333	        return;
334	    } else {
335	      ++PredI;
336	    }
337	  }
338	  assert(Erased && "Pred is not a predecessor of this block!");
339	  (void)Erased;
340	}
