342	void BinaryBasicBlock::removeDuplicateConditionalSuccessor(MCInst *CondBranch) {
343	  assert(succ_size() == 2 && Successors[0] == Successors[1] &&
344	         "conditional successors expected");
345	
346	  BinaryBasicBlock *Succ = Successors[0];
347	  const BinaryBranchInfo CondBI = BranchInfo[0];
348	  const BinaryBranchInfo UncondBI = BranchInfo[1];
349	
350	  eraseInstruction(findInstruction(CondBranch));
351	
352	  Successors.clear();
353	  BranchInfo.clear();
354	
355	  Successors.push_back(Succ);
356	
357	  uint64_t Count = COUNT_NO_PROFILE;
358	  if (CondBI.Count != COUNT_NO_PROFILE && UncondBI.Count != COUNT_NO_PROFILE)
359	    Count = CondBI.Count + UncondBI.Count;
360	  BranchInfo.push_back({Count, 0});
361	}
362	
363	void BinaryBasicBlock::updateJumpTableSuccessors() {
364	  const JumpTable *JT = getJumpTable();
365	  assert(JT && "Expected jump table instruction.");
366	
367	  // Clear existing successors.
368	  removeAllSuccessors();
369	
370	  // Generate the list of successors in deterministic order without duplicates.
371	  SmallVector<BinaryBasicBlock *, 16> SuccessorBBs;
372	  for (const MCSymbol *Label : JT->Entries) {
373	    BinaryBasicBlock *BB = getFunction()->getBasicBlockForLabel(Label);
374	    // Ignore __builtin_unreachable()
375	    if (!BB) {
376	      assert(Label == getFunction()->getFunctionEndLabel() &&
377	             "JT label should match a block or end of function.");
378	      continue;
379	    }
380	    SuccessorBBs.emplace_back(BB);
381	  }
382	  llvm::sort(SuccessorBBs,
383	             [](const BinaryBasicBlock *BB1, const BinaryBasicBlock *BB2) {
384	               return BB1->getInputOffset() < BB2->getInputOffset();
385	             });
386	  SuccessorBBs.erase(llvm::unique(SuccessorBBs), SuccessorBBs.end());
387	
388	  for (BinaryBasicBlock *BB : SuccessorBBs)
389	    addSuccessor(BB);
390	}
391	
392	void BinaryBasicBlock::adjustExecutionCount(double Ratio) {
393	  auto adjustedCount = [&](uint64_t Count) -> uint64_t {
394	    double NewCount = Count * Ratio;
395	    if (!NewCount && Count && (Ratio > 0.0))
396	      NewCount = 1;
397	    return NewCount;
398	  };
399	
400	  setExecutionCount(adjustedCount(getKnownExecutionCount()));
401	  for (BinaryBranchInfo &BI : branch_info()) {
402	    if (BI.Count != COUNT_NO_PROFILE)
403	      BI.Count = adjustedCount(BI.Count);
404	    if (BI.MispredictedCount != COUNT_INFERRED)
405	      BI.MispredictedCount = adjustedCount(BI.MispredictedCount);
406	  }
407	}
