409	bool BinaryBasicBlock::analyzeBranch(const MCSymbol *&TBB, const MCSymbol *&FBB,
410	                                     MCInst *&CondBranch,
411	                                     MCInst *&UncondBranch) {
412	  auto &MIB = Function->getBinaryContext().MIB;
413	  return MIB->analyzeBranch(Instructions.begin(), Instructions.end(), TBB, FBB,
414	                            CondBranch, UncondBranch);
415	}
416	
417	MCInst *BinaryBasicBlock::getTerminatorBefore(MCInst *Pos) {
418	  BinaryContext &BC = Function->getBinaryContext();
419	  auto Itr = rbegin();
420	  bool Check = Pos ? false : true;
421	  MCInst *FirstTerminator = nullptr;
422	  while (Itr != rend()) {
423	    if (!Check) {
424	      if (&*Itr == Pos)
425	        Check = true;
426	      ++Itr;
427	      continue;
428	    }
429	    if (BC.MIB->isTerminator(*Itr))
430	      FirstTerminator = &*Itr;
431	    ++Itr;
432	  }
433	  return FirstTerminator;
434	}
