436	bool BinaryBasicBlock::hasTerminatorAfter(MCInst *Pos) {
437	  BinaryContext &BC = Function->getBinaryContext();
438	  auto Itr = rbegin();
439	  while (Itr != rend()) {
440	    if (&*Itr == Pos)
441	      return false;
442	    if (BC.MIB->isTerminator(*Itr))
443	      return true;
444	    ++Itr;
445	  }
446	  return false;
447	}
