502	ErrorOr<std::pair<double, double>>
503	BinaryBasicBlock::getBranchStats(const BinaryBasicBlock *Succ) const {
504	  if (Function->hasValidProfile()) {
505	    uint64_t TotalCount = 0;
506	    uint64_t TotalMispreds = 0;
507	    for (const BinaryBranchInfo &BI : BranchInfo) {
508	      if (BI.Count != COUNT_NO_PROFILE) {
509	        TotalCount += BI.Count;
510	        TotalMispreds += BI.MispredictedCount;
511	      }
512	    }
513	
514	    if (TotalCount > 0) {
515	      auto Itr = llvm::find(Successors, Succ);
516	      assert(Itr != Successors.end());
517	      const BinaryBranchInfo &BI = BranchInfo[Itr - Successors.begin()];
518	      if (BI.Count && BI.Count != COUNT_NO_PROFILE) {
519	        if (TotalMispreds == 0)
520	          TotalMispreds = 1;
521	        return std::make_pair(double(BI.Count) / TotalCount,
522	                              double(BI.MispredictedCount) / TotalMispreds);
523	      }
524	    }
