565	BinaryBasicBlock *BinaryBasicBlock::splitAt(iterator II) {
566	  assert(II != end() && "expected iterator pointing to instruction");
567	
568	  BinaryBasicBlock *NewBlock = getFunction()->addBasicBlock();
569	
570	  // Adjust successors/predecessors and propagate the execution count.
571	  moveAllSuccessorsTo(NewBlock);
572	  addSuccessor(NewBlock, getExecutionCount(), 0);
573	
574	  // Set correct CFI state for the new block.
575	  NewBlock->setCFIState(getCFIStateAtInstr(&*II));
576	
577	  // Move instructions over.
578	  adjustNumPseudos(II, end(), -1);
579	  NewBlock->addInstructions(II, end());
580	  Instructions.erase(II, end());
581	
582	  return NewBlock;
